import { Command } from 'commander';
import ora from 'ora';
import { git } from '../utils/git.js';
import { summarizeCommits } from '../ai/prSummary.js';
import { notify } from '../utils/notify.js';

export function registerPR(program: Command) {
  const pr = program.command('pr').description('PR utilities');

  pr
    .command('summarize')
    .description('Generate PR title and description from commit history')
    .option('-n, --count <count>', 'Number of recent commits', '10')
    .option('--notify', 'Send summary to Slack/Discord if configured')
    .action(async opts => {
      const spinner = ora('Summarizing commits...').start();
      const log = await git().log({ n: parseInt(opts.count, 10) });
      const text = log.all.map(c => `${c.hash.slice(0, 7)} ${c.message}`).join('\n');
      const summary = await summarizeCommits(text);
      spinner.stop();
      console.log(summary);
      if (opts.notify) {
        await notify(`PR summary generated:\n${summary}`);
      }
    });
}
